export const orderStatuses = ["placed", "paid", "packed", "shipped", "delivered", "cancelled"] as const;

export type OrderStatus = (typeof orderStatuses)[number];

const nextStatus: Readonly<Record<Exclude<OrderStatus, "delivered" | "cancelled">, OrderStatus>> = {
  placed: "paid",
  paid: "packed",
  packed: "shipped",
  shipped: "delivered",
};

export function canTransition(from: OrderStatus, to: OrderStatus): boolean {
  return from in nextStatus && nextStatus[from as keyof typeof nextStatus] === to;
}

