import { DomainError } from "./errors";
import { canTransition, OrderStatus } from "./order-status";

export interface OrderLine {
  readonly productId: string;
  readonly quantity: number;
}

export class Order {
  public status: OrderStatus = "placed";

  public constructor(
    public readonly id: string,
    public readonly customerId: string,
    public readonly lines: readonly OrderLine[],
  ) {
    if (!id.trim() || !customerId.trim()) throw new DomainError("Order id and customer id are required");
    if (lines.length === 0) throw new DomainError("An order must contain at least one line");
    for (const line of lines) {
      if (!line.productId.trim() || !Number.isSafeInteger(line.quantity) || line.quantity <= 0) {
        throw new DomainError("Each order line needs a product id and positive integer quantity");
      }
    }
  }

  public advance(to: OrderStatus): void {
    if (!canTransition(this.status, to)) {
      throw new DomainError(`Cannot transition order from ${this.status} to ${to}`);
    }
    this.status = to;
  }

  public cancel(): void {
    if (this.status === "cancelled") throw new DomainError("Order is already cancelled");
    if (this.status === "shipped" || this.status === "delivered") {
      throw new DomainError("A shipped order cannot be cancelled");
    }
    this.status = "cancelled";
  }
}

